Assign to the nearest center, then move each center to its cluster mean.

```python
def kmeans_step(points, centers):
    groups = [[] for _ in centers]
    for p in points:
        d = [(p[0]-c[0])**2 + (p[1]-c[1])**2 for c in centers]
        groups[d.index(min(d))].append(p)
    return [[sum(q[0] for q in g)/len(g), sum(q[1] for q in g)/len(g)] if g else list(c)
            for g, c in zip(groups, centers)]
```

Single linkage is the minimum over cross pairs.

```python
import math

def single_link(a, b):
    return min(math.dist(p, q) for p in a for q in b)
```

A core point has at least m neighbours in its eps-ball, itself included.

```python
def core_points(xs, eps, m):
    return [i for i, x in enumerate(xs)
            if sum(abs(x - y) <= eps for y in xs) >= m]
```

Compare cohesion a with the nearest other cluster's separation b.

```python
def silhouette(x, own, others):
    if not own:
        return 0.0
    mean = lambda g: sum(abs(x - y) for y in g) / len(g)
    a, b = mean(own), min(mean(g) for g in others)
    return (b - a) / max(a, b)
```

A pair agrees when both labelings say same or both say different.

```python
def rand_index(a, b):
    n = len(a)
    if n < 2:
        return 1.0
    pairs = [(i, j) for i in range(n) for j in range(i+1, n)]
    agree = sum((a[i] == a[j]) == (b[i] == b[j]) for i, j in pairs)
    return agree / len(pairs)
```

Sort descending and accumulate until the share reaches the target.

```python
def n_components(eigs, target):
    e = sorted(eigs, reverse=True)
    total, acc = sum(e), 0.0
    for k, v in enumerate(e, 1):
        acc += v
        if acc / total >= target - 1e-12:
            return k
```

Normalise the dot product by both lengths; guard the zero vector.

```python
import math

def cosine(u, v):
    nu, nv = math.sqrt(sum(a*a for a in u)), math.sqrt(sum(b*b for b in v))
    if nu == 0 or nv == 0:
        return 0.0
    return sum(a*b for a, b in zip(u, v)) / (nu * nv)
```

Smooth each category mean toward the global mean; unseen has zero count.

```python
def target_encode(train_cats, train_y, test_cats, m):
    g = sum(train_y) / len(train_y)
    def enc(c):
        ys = [y for k, y in zip(train_cats, train_y) if k == c]
        return (sum(ys) + m * g) / (len(ys) + m)
    return [enc(c) for c in test_cats]
```

